for i in range(1,15):
    try:
        df = pd.read_csv(eval(f"experiment_{i}_csv"))
        cols = df.columns.tolist()
        # print key means
        summary = {}
        for c in ['LineFlushRate','PhStabilizer','WaterClarityScore','DissolvedMetal','MetalLevel','Iron','BiofilmSloughing','UVDose']:
            if c in df.columns:
                summary[c]=round(df[c].mean(),2)
        print(i, summary)
    except Exception as e:
        print(i, "err", e)

